'use client';
import { useState, useEffect } from 'react';
import OrderTable from '@/components/orderTable';
import CustomerTable from '@/components/customerTable';
import ExportButton from '@/components/exportButton';

type Tab = 'orders' | 'customers';

export default function Dashboard() {
  const [activeTab, setActiveTab] = useState<Tab>('orders');
  const [orders, setOrders] = useState<any[]>([]);
  const [customers, setCustomers] = useState<any[]>([]);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const fetchOrders = async () => {
    setLoading(true);
    setError(null);
    try {
      const res = await fetch('/api/orders');
      if (!res.ok) throw new Error('Failed to load orders');
      const data = await res.json();
      setOrders(data);
    } catch (e: any) {
      setError(e.message);
    } finally {
      setLoading(false);
    }
  };

  const fetchCustomers = async () => {
    setLoading(true);
    setError(null);
    try {
      const res = await fetch('/api/customers');
      if (!res.ok) throw new Error('Failed to load customers');
      const data = await res.json();
      setCustomers(data);
    } catch (e: any) {
      setError(e.message);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    if (activeTab === 'orders') fetchOrders();
    else fetchCustomers();
  }, [activeTab]);

  const currentData = activeTab === 'orders' ? orders : customers;

  return (
    <div className="space-y-6">
      <h1 className="text-2xl font-semibold">Ember & Oak – Order Desk</h1>
      <div className="flex gap-4">
        <button
          className={`px-4 py-2 rounded ${
            activeTab === 'orders' ? 'bg-indigo-600 text-white' : 'bg-gray-200'
          }`}
          onClick={() => setActiveTab('orders')}
        >
          This Week Orders
        </button>
        <button
          className={`px-4 py-2 rounded ${
            activeTab === 'customers' ? 'bg-indigo-600 text-white' : 'bg-gray-200'
          }`}
          onClick={() => setActiveTab('customers')}
        >
          Customers
        </button>
        <ExportButton data={currentData} filename={activeTab} />
      </div>
      {loading && <p className="text-gray-600">Loading…</p>}
      {error && <p className="text-red-600">{error}</p>}
      {!loading && !error && (
        <>
          {activeTab === 'orders' ? (
            <OrderTable orders={orders} refresh={fetchOrders} />
          ) : (
            <CustomerTable customers={customers} refresh={fetchCustomers} />
          )}
        </>
      )}
    </div>
  );
}

