import { NextResponse } from 'next/server';
import { Order, OrderStatus } from '@/lib/types';
import { getOrders, setOrders } from '@/lib/store';
import { v4 as uuidv4 } from 'uuid';

export async function GET() {
  try {
    const orders = await getOrders();
    return NextResponse.json(orders);
  } catch (e: any) {
    return NextResponse.json({ error: e.message }, { status: 500 });
  }
}

export async function POST(request: Request) {
  try {
    const body = await request.json();
    const { customerId, product, quantity, price, roastBatchId } = body;
    if (!customerId || !product || !quantity || !price) {
      return NextResponse.json({ error: 'Missing required fields' }, { status: 400 });
    }
    const newOrder: Order = {
      id: uuidv4(),
      customerId,
      product,
      quantity,
      price,
      status: 'pending' as OrderStatus,
      roastBatchId: roastBatchId ?? null,
      createdAt: new Date().toISOString(),
    };
    const orders = await getOrders();
    orders.push(newOrder);
    await setOrders(orders);
    return NextResponse.json(newOrder, { status: 201 });
  } catch (e: any) {
    return NextResponse.json({ error: e.message }, { status: 500 });
  }
}

export async function PATCH(request: Request) {
  try {
    const body = await request.json();
    const { id, status } = body;
    if (!id || !status) {
      return NextResponse.json({ error: 'Missing id or status' }, { status: 400 });
    }
    const orders = await getOrders();
    const order = orders.find(o => o.id === id);
    if (!order) {
      return NextResponse.json({ error: 'Order not found' }, { status: 404 });
    }
    order.status = status as OrderStatus;
    await setOrders(orders);
    return NextResponse.json(order);
  } catch (e: any) {
    return NextResponse.json({ error: e.message }, { status: 500 });
  }
}

import { NextResponse } from 'next/server';
import { getCustomers, saveCustomers } from '../../../lib/store';
import { Customer } from '../../../lib/types';

export async function GET() {
  const customers = await getCustomers();
  return NextResponse.json(customers);
}

export async function POST(request: Request) {
  const data = await request.json();
  if (!data.name || !data.email) {
    return NextResponse.json({ error: 'Missing name or email' }, { status: 400 });
  }
  const customers = await getCustomers();
  const newCustomer: Customer = {
    id: crypto.randomUUID(),
    name: data.name,
    email: data.email,
    address: data.address ?? '',
    createdAt: new Date().toISOString(),
  };
  customers.push(newCustomer);
  await saveCustomers(customers);
  return NextResponse.json(newCustomer, { status: 201 });
}

export async function PUT(request: Request) {
  const data = await request.json();
  if (!data.id) {
    return NextResponse.json({ error: 'Missing id' }, { status: 400 });
  }
  const customers = await getCustomers();
  const index = customers.findIndex(c => c.id === data.id);
  if (index === -1) {
    return NextResponse.json({ error: 'Customer not found' }, { status: 404 });
  }
  const updated: Customer = {
    ...customers[index],
    name: data.name ?? customers[index].name,
    email: data.email ?? customers[index].email,
    address: data.address ?? customers[index].address,
  };
  customers[index] = updated;
  await saveCustomers(customers);
  return NextResponse.json(updated);
}

import { promises as fs } from 'fs';
import path from 'path';
import { Order, Customer } from './types';

const dataDir = path.join(process.cwd(), 'data');
const ordersPath = path.join(dataDir, 'orders.json');
const customersPath = path.join(dataDir, 'customers.json');

async function ensureFile(filePath: string) {
  try {
    await fs.access(filePath);
  } catch {
    await fs.mkdir(path.dirname(filePath), { recursive: true });
    await fs.writeFile(filePath, '[]');
  }
}

export async function getOrders(): Promise<Order[]> {
  await ensureFile(ordersPath);
  const text = await fs.readFile(ordersPath, 'utf8');
  return JSON.parse(text) as Order[];
}

export async function saveOrders(orders: Order[]) {
  await ensureFile(ordersPath);
  await fs.writeFile(ordersPath, JSON.stringify(orders, null, 2));
}

export async function getCustomers(): Promise<Customer[]> {
  await ensureFile(customersPath);
  const text = await fs.readFile(customersPath, 'utf8');
  return JSON.parse(text) as Customer[];
}

export async function saveCustomers(customers: Customer[]) {
  await ensureFile(customersPath);
  await fs.writeFile(customersPath, JSON.stringify(customers, null, 2));
}

export type OrderStatus = 'pending' | 'roasting' | 'shipped' | 'cancelled';
export type RoastStatus = 'pending' | 'roasting' | 'completed';

export interface RoastBatch {
  id: string;
  roastDate: string;
  batchSize: number;
  status: RoastStatus;
}

export interface Order {
  id: string;
  customerId: string;
  subscriptionStart: string;
  quantity: number;
  roastBatchId?: string;
  status: OrderStatus;
  totalPrice: number;
  createdAt: string;
}

export interface Customer {
  id: string;
  name: string;
  email: string;
  address: string;
  createdAt: string;
}

export function toCSV<T>(records: T[], columns: (keyof T)[]): string {
  const escape = (value: unknown) => {
    if (value == null) return '';
    const str = String(value);
    if (/[",\n]/.test(str)) {
      return `"${str.replace(/"/g, '""')}"`;
    }
    return str;
  };
  const header = columns.map(col => escape(col)).join(',');
  const rows = records.map(rec => columns.map(col => escape(rec[col])).join(','));
  return [header, ...rows].join('\n');
}

