'use client';
import { useEffect, useState } from 'react';
import { Order } from '@/lib/types';
import ExportButton from '@/components/exportButton';
import { generateCSV } from '@/lib/csv';

type SortKey = keyof Order;

export default function OrderTable() {
  const [orders, setOrders] = useState<Order[]>([]);
  const [display, setDisplay] = useState<Order[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [search, setSearch] = useState('');
  const [statusFilter, setStatusFilter] = useState('All');
  const [sortKey, setSortKey] = useState<SortKey>('orderDate');
  const [sortDir, setSortDir] = useState<'asc' | 'desc'>('asc');

  useEffect(() => {
    fetch('/api/orders')
      .then((r) => {
        if (!r.ok) throw new Error('Failed to load orders');
        return r.json();
      })
      .then((data: Order[]) => {
        setOrders(data);
        setLoading(false);
      })
      .catch((e) => {
        setError(e.message);
        setLoading(false);
      });
  }, []);

  useEffect(() => {
    let filtered = orders;
    if (search) {
      const term = search.toLowerCase();
      filtered = filtered.filter(
        (o) =>
          o.customerName.toLowerCase().includes(term) ||
          o.subscriptionType.toLowerCase().includes(term)
      );
    }
    if (statusFilter !== 'All') {
      filtered = filtered.filter((o) => o.status === statusFilter);
    }
    filtered = filtered.slice().sort((a, b) => {
      const av = a[sortKey];
      const bv = b[sortKey];
      if (av === bv) return 0;
      const comp = av > bv ? 1 : -1;
      return sortDir === 'asc' ? comp : -comp;
    });
    setDisplay(filtered);
  }, [orders, search, statusFilter, sortKey, sortDir]);

  const toggleSort = (key: SortKey) => {
    if (sortKey === key) {
      setSortDir(sortDir === 'asc' ? 'desc' : 'asc');
    } else {
      setSortKey(key);
      setSortDir('asc');
    }
  };

  const updateStatus = async (id: string, status: string) => {
    const res = await fetch(`/api/orders/${id}`, {
      method: 'PATCH',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ status }),
    });
    if (!res.ok) {
      alert('Unable to update status');
      return;
    }
    const updated: Order = await res.json();
    setOrders((prev) => prev.map((o) => (o.id === id ? updated : o)));
  };

  if (loading) return <p className="p-4">Loading orders…</p>;
  if (error) return <p className="p-4 text-red-600">Error: {error}</p>;

  return (
    <section className="p-4">
      <h1 className="text-2xl font-semibold mb-4">This Week’s Subscription Orders</h1>
      <div className="flex items-center gap-4 mb-4">
        <input
          type="text"
          placeholder="Search by customer or subscription"
          value={search}
          onChange={(e) => setSearch(e.target.value)}
          className="border rounded px-2 py-1 flex-1"
        />
        <select
          value={statusFilter}
          onChange={(e) => setStatusFilter(e.target.value)}
          className="border rounded px-2 py-1"
        >
          <option value="All">All statuses</option>
          <option value="Pending">Pending</option>
          <option value="Roasted">Roasted</option>
          <option value="Shipped">Shipped</option>
        </select>
        <ExportButton data={display} filename="orders.csv" />
      </div>
      {display.length === 0 ? (
        <p className="p-4 text-gray-600">No orders match your criteria.</p>
      ) : (
        <table className="w-full border-collapse">
          <thead>
            <tr className="bg-emerald-100">
              <th
                className="cursor-pointer p-2 text-left"
                onClick={() => toggleSort('orderDate')}
              >
                Order Date {sortKey === 'orderDate' && (sortDir === 'asc' ? '▲' : '▼')}
              </th>
              <th className="p-2 text-left">Customer</th>
              <th className="p-2 text-left">Subscription</th>
              <th className="p-2 text-left">Qty (g)</th>
              <th className="p-2 text-left">Revenue</th>
              <th className="p-2 text-left">Roast Batch</th>
              <th
                className="cursor-pointer p-2 text-left"
                onClick={() => toggleSort('status')}
              >
                Status {sortKey === 'status' && (sortDir === 'asc' ? '▲' : '▼')}
              </th>
            </tr>
          </thead>
          <tbody>
            {display.map((o) => (
              <tr key={o.id} className="border-b">
                <td className="p-2">{new Date(o.orderDate).toLocaleDateString()}</td>
                <td className="p-2">{o.customerName}</td>
                <td className="p-2">{o.subscriptionType}</td>
                <td className="p-2">{o.quantity}</td>
                <td className="p-2">{`$${o.totalPrice.toFixed(2)}`}</td>
                <td className="p-2">{o.roastBatch || '—'}</td>
                <td className="p-2">
                  <select
                    value={o.status}
                    onChange={(e) => updateStatus(o.id, e.target.value)}
                    className="border rounded px-1 py-0.5"
                  >
                    <option value="Pending">Pending</option>
                    <option value="Roasted">Roasted</option>
                    <option value="Shipped">Shipped</option>
                  </select>
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      )}
    </section>
  );
}

